var fs = require("fs");
var path = require("path");
var childProcess = require("child_process");

var root = path.resolve(__dirname, "..");
var distDir = path.join(root, "dist");
var starterDir = path.join(distDir, "starter-package");
var zipPath = path.join(distDir, "zabbix-js-starter.zip");

var essentialFiles = [
  "README.md",
  "todo.md",
  "agent-memory.md",
  ".gitignore",
  "package.json",
  "script.js",
  "params.example.json",
  "harness/run.js",
  "harness/zabbix-globals.js",
  "harness/HttpRequest.js",
  "tools/init-project.js",
  "tools/build-zabbix-script.js",
  "tools/check-duktape.js",
  "tools/dev-check.js",
  "tools/scan-secrets.js",
  ".vscode/launch.json",
  ".vscode/tasks.json",
  ".eslintrc.cjs"
];

function ensureDir(dirPath) {
  fs.mkdirSync(dirPath, { recursive: true });
}

function copyEssentialFiles() {
  var i;
  var sourcePath;
  var targetPath;

  for (i = 0; i < essentialFiles.length; i += 1) {
    sourcePath = path.join(root, essentialFiles[i]);
    targetPath = path.join(starterDir, essentialFiles[i]);

    if (!fs.existsSync(sourcePath)) {
      throw new Error("Required file not found: " + essentialFiles[i]);
    }

    ensureDir(path.dirname(targetPath));
    fs.copyFileSync(sourcePath, targetPath);
  }
}

function writeStarterNotes() {
  var notes = [
    "# Starter Package Notes",
    "",
    "This is a minimal offline starter package for developing JavaScript used in Zabbix.",
    "It lets you write and test your script locally before pasting it into Zabbix.",
    "",
    "## First-Time Setup",
    "",
    "Run these commands once after unzipping:",
    "",
    "```",
    "npm install",
    "npm run init",
    "```",
    "",
    "`npm run init` creates your local `params.json` from the example file.",
    "Edit `params.json` to match your target URL and expected values.",
    "",
    "## Your Day-to-Day Workflow",
    "",
    "1. Edit `script.js` — this is your main script file.",
    "2. Test it locally:",
    "   ```",
    "   npm run debug:script-item",
    "   ```",
    "3. When ready, build the Zabbix-ready version:",
    "   ```",
    "   npm run build:zabbix",
    "   ```",
    "4. Copy the contents of `script.zabbix.js` into Zabbix.",
    "",
    "## VS Code Tasks (Recommended)",
    "",
    "Open the Command Palette (`Ctrl+Shift+P` / `Cmd+Shift+P`), choose",
    "**Tasks: Run Task**, and pick from the list. Each task has a description",
    "explaining what it does.",
    "",
    "## Key Files",
    "",
    "| File | Purpose |",
    "|------|---------|",
    "| `script.js` | Your script — edit this |",
    "| `params.json` | Your local test inputs — never commit this |",
    "| `params.example.json` | Safe example inputs — commit this |",
    "| `script.zabbix.js` | Auto-generated — paste this into Zabbix |",
    "",
    "## Important Notes",
    "",
    "- `params.json` is not included in this package — create it via `npm run init`.",
    "- Never commit `params.json` — it may contain tokens or credentials.",
    "- `script.zabbix.js` is auto-generated by `npm run build:zabbix` — do not edit it directly.",
    "- Zabbix runs ES5 JavaScript (Duktape engine) — avoid arrow functions, `let`, `const`, template literals.",
    "- Run `npm run check` before submitting your script to catch compatibility issues.",
    ""
  ].join("\n");

  fs.writeFileSync(path.join(starterDir, "STARTER-NOTES.md"), notes, "utf8");
}

function zipStarterDirectory() {
  var result;

  result = childProcess.spawnSync("zip", ["-rq", zipPath, "."], {
    cwd: starterDir,
    encoding: "utf8"
  });

  if (result.error || result.status !== 0) {
    process.stdout.write("Starter folder created at dist/starter-package\n");
    process.stdout.write("zip command not available. Zip file was not created.\n");
    return;
  }

  process.stdout.write("Starter folder created at dist/starter-package\n");
  process.stdout.write("Starter zip created at dist/zabbix-js-starter.zip\n");
}

function main() {
  fs.rmSync(starterDir, { recursive: true, force: true });
  fs.rmSync(zipPath, { force: true });
  ensureDir(starterDir);

  copyEssentialFiles();
  writeStarterNotes();
  zipStarterDirectory();
}

main();
